mapper.sql:
FROM arc_profile p LEFT JOIN stu_student s ON s.id = p.student_id LEFT JOIN arc_profile bp ON bp.student_id = p.student_id AND bp.academic_year = p.academic_year AND bp.section_code = 'BASIC' LEFT JOIN arc_profile_item ci ON ci.profile_id = bp.id AND ci.field_code = 'basic.classId' LEFT JOIN org_class c ON c.class_code = WHERE p.academic_year = #{academicYear}
AND c.counselor_user_id = #{counselorId} AND c.status = 1
AND = #{classCode}
